import * as THREE from 'three';
import {GLTFExporter} from './vendor/GLTFExporter.js';
import {OrbitControls} from './vendor/OrbitControls.js';
const $=id=>document.getElementById(id),host=$('viewport');
const scene=new THREE.Scene();scene.background=new THREE.Color('#e8ecdf');
const camera=new THREE.PerspectiveCamera(60,1,.1,150);camera.position.set(24,26,24);
const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;host.append(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.49;controls.minDistance=.5;controls.maxDistance=65;controls.target.set(0,0,-9);
scene.add(new THREE.HemisphereLight('#eef5ff','#7c8061',2.5));const sun=new THREE.DirectionalLight('#fff0d4',3);sun.position.set(-10,25,15);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-22,right:22,top:22,bottom:-22});sun.shadow.normalBias=.035;scene.add(sun);
const areaLabels=[];const parts=[],group=new THREE.Group();scene.add(group);
async function readModel(){const response=await fetch('model.glb?v=greens8');if(!response.ok)throw Error('Model could not be loaded');const data=await response.arrayBuffer(),view=new DataView(data);if(view.getUint32(0,true)!==0x46546c67||view.getUint32(4,true)!==2)throw Error('Invalid GLB');let json,bin;for(let p=12;p<data.byteLength;){const size=view.getUint32(p,true),type=view.getUint32(p+4,true);p+=8;if(type===0x4e4f534a)json=JSON.parse(new TextDecoder().decode(new Uint8Array(data,p,size)));if(type===0x004e4942)bin=data.slice(p,p+size);p+=size;}
const types={5121:Uint8Array,5123:Uint16Array,5125:Uint32Array,5126:Float32Array},counts={SCALAR:1,VEC2:2,VEC3:3,VEC4:4};function attribute(index){const a=json.accessors[index],v=json.bufferViews[a.bufferView],Type=types[a.componentType];if(!Type||v.byteStride)throw Error('Unsupported attribute');return new THREE.BufferAttribute(new Type(bin,(v.byteOffset||0)+(a.byteOffset||0),a.count*counts[a.type]),counts[a.type],!!a.normalized);}
for(const node of json.nodes){if(node.mesh===undefined)continue;for(const p of json.meshes[node.mesh].primitives){const geo=new THREE.BufferGeometry();geo.setAttribute('position',attribute(p.attributes.POSITION));if(p.indices!==undefined)geo.setIndex(attribute(p.indices));geo.computeVertexNormals();const c=attribute(p.attributes.COLOR_0),color=new THREE.Color(c.getX(0),c.getY(0),c.getZ(0)).convertSRGBToLinear();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color,roughness:.95,flatShading:!/leaves|grass|foliage|shrub|underplant/.test(node.name)}));mesh.name=node.name;mesh.castShadow=true;mesh.receiveShadow=true;if(node.matrix)mesh.applyMatrix4(new THREE.Matrix4().fromArray(node.matrix));group.add(mesh);parts.push(mesh);}}
for(const m of parts){m.userData.basePosition=m.position.toArray();}applyDimensions();window.joybromo={scene,camera,renderer,parts};visibility();}
const presets={alcove:{p:[-10.2,2.05,-5.7],t:[-6.5,1.5,-11.1],title:'The recessed corner',note:'Existing roofed alcove from first-day photos. Your intended future photo spot; depth is an adjustable estimate.'},overview:{p:[32,32,34],t:[2,0,-10],title:'The mapped property',note:'L-shaped house, parking and existing seating follow your illustrated denah.'},arrival:{p:[0,1.7,-.3],t:[-3,1.4,-10],title:'At the gate',note:'Open bar on the left. House farther back, with adjustable distance.'},booth:{p:[-3.5,3.4,-6.5],t:[-10.6,1.4,-4.2],title:'The cream-and-green bar',note:'Curved scalloped awning, corrugated cream body and green serving frame.'},courtyard:{p:[1,2,-3],t:[-3,1.5,-10],title:'Inside the courtyard',note:'House position follows the distance slider.'},side:{p:[-12.65,2.1,-.1],t:[-12.7,1,-6],title:'The narrow side strip',note:'Weathered concrete, low wall, opposing benches and the tree behind the kiosk.'},house:{p:[0,2.6,-.8],t:[-3.6,1.8,-10],title:'The existing house front',note:'Uneven branching trees, mixed low planting and a grass-and-soil edge. Spacing remains approximate.'},garden:{p:[-12.6,4,-13.6],t:[-5,1.2,-19.4],title:'The planted backyard',note:'Current trees and groundcover remain; parking is a future use.'},closed:{p:[-.5,3.5,-1],t:[4.4,1.1,-6.5],title:'Covered seating interior',note:'Green table, wooden chairs, cream cabinet and screening from first-day photos.'},plan:{p:[0,48,-8.99],t:[0,0,-9],title:'Satellite footprint',note:'Compare the L-shaped house, parking, expansion strip and black-marked seating.'}};
let move=null;function setView(key){const v=presets[key];areaLabels.forEach(s=>s.visible=['overview','plan'].includes(key));guide.visible=['overview','plan','arrival'].includes(key);if(['closed','plan','house','garden','booth','side','alcove'].includes(key)){$('roofs').checked=!['closed','plan'].includes(key);$('trees').checked=false;if(key==='closed')$('screens').checked=false;visibility();}if(['arrival','courtyard'].includes(key))v.t=[-1.5,1.4,-Number($('distance').value)];camera.fov=['arrival','closed','house','side','alcove'].includes(key)?60:40;camera.updateProjectionMatrix();move={from:camera.position.clone(),a:controls.target.clone(),to:new THREE.Vector3(...v.p),b:new THREE.Vector3(...v.t),start:performance.now()};$('view-title').textContent=v.title;$('view-note').textContent=v.note;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===key));}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));controls.addEventListener('start',()=>move=null);
function visibility(){for(const m of parts)m.visible=(!/roof|awning/.test(m.name)||$('roofs').checked)&&(!(/tree-crown/.test(m.name)&&/leaves/.test(m.name))||$('trees').checked)&&(!/^closed-screen/.test(m.name)||$('screens').checked)&&(!/^road$|sidewalk|tactile/.test(m.name)||$('surroundings').checked);}
for(const id of ['roofs','trees','surroundings','screens'])$(id).onchange=visibility;
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;renderer.domElement.onpointerdown=e=>down=[e.clientX,e.clientY];renderer.domElement.onpointerup=e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(parts.filter(p=>p.visible))[0];$('selected').textContent=hit?hit.object.name.replaceAll('-',' '):'Click a part to identify it.';};
$('photos').onclick=()=>$('references').showModal();$('close').onclick=()=>$('references').close();
const guide=new THREE.Group();scene.add(guide);const lineMat=new THREE.LineBasicMaterial({color:0x9e622e,depthTest:false});for(const points of [[[0,.13,-10],[0,.13,0]],[[-.25,.13,-10],[.25,.13,-10]],[[-.25,.13,0],[.25,.13,0]]]){const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p))),lineMat);line.renderOrder=10;guide.add(line);}
const canvas=document.createElement('canvas');canvas.width=640;canvas.height=96;const ctx=canvas.getContext('2d');ctx.fillStyle='#faf9f3';ctx.fillRect(0,0,640,96);ctx.fillStyle='#704727';ctx.font='30px sans-serif';ctx.textAlign='center';ctx.fillText('Gate to house ≈ 5 m',320,58);const label=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(canvas),depthTest:false,sizeAttenuation:false,toneMapped:false}));label.position.set(.6,.45,7.8);label.scale.set(.14,.021,1);label.renderOrder=11;guide.add(label);
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();}).observe(host);
function animate(t){requestAnimationFrame(animate);if(move){const k=Math.min((t-move.start)/700,1),s=k*k*(3-2*k);camera.position.lerpVectors(move.from,move.to,s);controls.target.lerpVectors(move.a,move.b,s);if(k===1)move=null;}controls.update();renderer.render(scene,camera);}requestAnimationFrame(animate);
readModel().then(()=>{const requested=new URLSearchParams(location.search).get('view');const key=presets[requested]?requested:'overview';setView(key);move=null;camera.position.set(...presets[key].p);controls.target.set(...presets[key].t);controls.update();}).catch(e=>{$('status').textContent='Could not load model';$('view-note').textContent=e.message;console.error(e);});

function textLabel(text){ctx.clearRect(0,0,640,96);ctx.fillStyle='#faf9f3';ctx.fillRect(0,0,640,96);ctx.fillStyle='#704727';ctx.fillText(text,320,58);label.material.map.needsUpdate=true;}
const dimensionKey='joybromo-photo-estimates-v4';
try{const saved=JSON.parse(localStorage.getItem(dimensionKey)||'null');if(saved)for(const id of ['distance','yard','path','alcove'])if(Number.isFinite(saved[id]))$(id).value=saved[id];}catch{}
function applyDimensions(){const distance=Number($('distance').value),yard=Number($('yard').value),width=Number($('path').value),alcove=Number($('alcove').value),shift=10-distance;
 for(const mesh of parts){const name=mesh.name;mesh.position.fromArray(mesh.userData.basePosition);if(name.startsWith('house-'))mesh.position.z+=shift;
 if(/^house-alcove-(stored-low-slat|slat-support|aqua-container)/.test(name)){mesh.geometry.computeBoundingBox();const z=mesh.geometry.boundingBox.getCenter(new THREE.Vector3()).z;mesh.position.z+=(-10+(z+10)*alcove/1.6)-z;}
 if(name.startsWith('house-alcove-back-'))mesh.position.z-=alcove-1.6;
 if(name.startsWith('house-alcove-stretch-')){mesh.scale.z=alcove/1.6;mesh.position.z+=-10*(1-mesh.scale.z);}
 if(name==='house-alcove-left-rear'){mesh.scale.z=(6.45-alcove)/4.85;mesh.position.z+=-16.45*(1-mesh.scale.z);}

 if(name==='worn-courtyard'){mesh.scale.z=distance/10;mesh.position.z=0;}
 if(name.startsWith('garden-grass-')){mesh.scale.z=yard/6.4;mesh.position.z=-16.1*(1-mesh.scale.z);}else if(name.startsWith('garden-')){mesh.geometry.computeBoundingBox();const z=mesh.geometry.boundingBox.getCenter(new THREE.Vector3()).z;mesh.position.z=(-16.1+(z+16.1)*yard/6.4)-z;}if(name==='backyard-parking-area'){mesh.scale.z=yard/6.4;mesh.position.z=-16.1*(1-yard/6.4);}
 if(name==='side-access-path'){mesh.scale.x=width/1.65;mesh.position.x=-12.72*(1-width/1.65);}if(name==='access-to-backyard'){mesh.scale.z=width/1.4;mesh.position.z=-22.5*(1-width/1.4);}
 }
 guide.children.forEach(child=>{child.scale.z=distance/10;child.position.z=0;});label.scale.set(.14,.021,1);label.position.set(.6,.45,-distance/2);textLabel('Gate to house ≈ '+distance.toFixed(1)+' m');
 $('alcove-value').textContent=alcove.toFixed(1)+' m';$('distance-value').textContent=distance.toFixed(1)+' m';$('yard-value').textContent=yard.toFixed(1)+' m';$('path-value').textContent=width.toFixed(2)+' m';$('status').textContent='Gate to house ≈ '+distance.toFixed(1)+' m';
}
for(const id of ['distance','yard','path','alcove'])$(id).oninput=()=>{applyDimensions();try{localStorage.setItem(dimensionKey,JSON.stringify(Object.fromEntries(['distance','yard','path','alcove'].map(k=>[k,Number($(k).value)]))));$('save-state').textContent='Estimates saved in this browser.';}catch{$('save-state').textContent='Could not save locally. Download to keep your changes.';}};
$('reset-dimensions').onclick=()=>{for(const [id,v] of [['distance',10],['yard',6.4],['path',1.65],['alcove',1.6]])$(id).value=v;$('distance').oninput();};
$('export').onclick=async()=>{const button=$('export');button.disabled=true;button.textContent='Preparing model…';const hidden=parts.filter(p=>!p.visible);try{parts.forEach(p=>p.visible=true);group.updateMatrixWorld(true);group.userData.estimates={gateToHouseM:Number($('distance').value),backyardDepthM:Number($('yard').value),pathWidthM:Number($('path').value),alcoveDepthM:Number($('alcove').value)};const data=await new GLTFExporter().parseAsync(group,{binary:true});const u=URL.createObjectURL(new Blob([data],{type:'model/gltf-binary'}));const a=document.createElement('a');a.href=u;a.download='JoyBromo-adjusted-existing.glb';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}catch(e){$('save-state').textContent='Export failed: '+e.message;}finally{hidden.forEach(p=>p.visible=false);button.disabled=false;button.textContent='Download adjusted model ↓';}};

function areaLabel(text,x,z){const c=document.createElement('canvas');c.width=640;c.height=96;const k=c.getContext('2d');k.fillStyle='#faf9f3';k.fillRect(0,0,640,96);k.fillStyle='#345b46';k.font='30px sans-serif';k.textAlign='center';k.fillText(text,320,58);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),depthTest:false,sizeAttenuation:false,toneMapped:false}));sprite.position.set(x,.5,z);sprite.scale.set(.12,.018,1);sprite.renderOrder=12;scene.add(sprite);areaLabels.push(sprite);}
areaLabel('Planted yard / future parking',-5.5,-19.3);areaLabel('Side access',-11.1,-10);areaLabel('Potential expansion',13,-12);

for(const [x,z] of [[5.1,-5.2],[7.6,-11.4]]){const light=new THREE.PointLight('#fff0d1',8,7,2);light.position.set(x,2.6,z);scene.add(light);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.075,10,8),new THREE.MeshStandardMaterial({color:'#fff3d2',emissive:'#ffe6a3',emissiveIntensity:2}));bulb.position.copy(light.position);scene.add(bulb);}

function barSign(text,x,y,z,w,h,bg,fg){const c=document.createElement('canvas');c.width=640;c.height=320;const k=c.getContext('2d');k.fillStyle=bg;k.fillRect(0,0,640,320);k.fillStyle=fg;k.font='bold 68px sans-serif';k.textAlign='center';k.textBaseline='middle';k.fillText(text,320,160,590);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const panel=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshStandardMaterial({map:tex,roughness:1}));panel.rotation.y=Math.PI/2;panel.position.set(x,y,z);group.add(panel);}
barSign('COFFEE',-8.58,1.46,-4.2,1.3,.22,'#3d6052','#eee8d5');
for(const [i,text] of ['SANDWICH','CHOCOLATE','ICE CREAM'].entries())barSign(text,-11.85,1.9,-5.35+i*1.15,.65,.9,'#ded4b3','#484937');
